CREATE TABLE lifecycle_observer(owner TEXT PRIMARY KEY REFERENCES owners(owner),override_enabled INTEGER NOT NULL CHECK(override_enabled IN (0,1)),observed_at INTEGER NOT NULL CHECK(observed_at>=0),transition_seq INTEGER NOT NULL CHECK(transition_seq>=0));
CREATE TABLE lifecycle_invitations(owner TEXT NOT NULL REFERENCES owners(owner),coordinate TEXT NOT NULL,queued_at INTEGER NOT NULL CHECK(queued_at>=0),PRIMARY KEY(owner,coordinate));
CREATE TABLE notice_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,owner TEXT NOT NULL REFERENCES owners(owner),identity TEXT NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN ('pause','resume','invitation')),context_json TEXT NOT NULL,relays_json TEXT NOT NULL,created_at INTEGER NOT NULL CHECK(created_at>=0),UNIQUE(owner,identity));
CREATE TABLE notice_destinations(owner TEXT NOT NULL,identity TEXT NOT NULL,destination TEXT NOT NULL,unsigned_json TEXT NOT NULL,signed_json TEXT,canceled INTEGER NOT NULL DEFAULT 0 CHECK(canceled IN (0,1)),lease_id TEXT,lease_until INTEGER NOT NULL DEFAULT 0,attempted_at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(owner,identity,destination),FOREIGN KEY(owner,identity) REFERENCES notice_events(owner,identity));
CREATE TABLE notice_receipts(owner TEXT NOT NULL,identity TEXT NOT NULL,destination TEXT NOT NULL,relay TEXT NOT NULL,acknowledged_at INTEGER NOT NULL CHECK(acknowledged_at>=0),PRIMARY KEY(owner,identity,destination,relay),FOREIGN KEY(owner,identity,destination) REFERENCES notice_destinations(owner,identity,destination));
CREATE TRIGGER immutable_notice BEFORE UPDATE ON notice_events BEGIN SELECT RAISE(ABORT,'notice is frozen'); END;
CREATE TRIGGER retained_notice BEFORE DELETE ON notice_events BEGIN SELECT RAISE(ABORT,'notice is retained'); END;
CREATE TRIGGER frozen_notice_destination BEFORE UPDATE ON notice_destinations WHEN NEW.owner IS NOT OLD.owner OR NEW.identity IS NOT OLD.identity OR NEW.destination IS NOT OLD.destination OR NEW.unsigned_json IS NOT OLD.unsigned_json OR (OLD.signed_json IS NOT NULL AND NEW.signed_json IS NOT OLD.signed_json) OR NEW.canceled<OLD.canceled BEGIN SELECT RAISE(ABORT,'notice destination cannot change'); END;
CREATE TRIGGER retained_notice_destination BEFORE DELETE ON notice_destinations BEGIN SELECT RAISE(ABORT,'notice destination is retained'); END;
CREATE TRIGGER immutable_notice_receipt BEFORE UPDATE ON notice_receipts BEGIN SELECT RAISE(ABORT,'notice receipt is immutable'); END;
CREATE TRIGGER retained_notice_receipt BEFORE DELETE ON notice_receipts BEGIN SELECT RAISE(ABORT,'notice receipt is retained'); END;
CREATE TRIGGER monotone_lifecycle BEFORE UPDATE ON lifecycle_observer WHEN NEW.owner IS NOT OLD.owner OR NEW.observed_at<OLD.observed_at OR NEW.transition_seq<OLD.transition_seq BEGIN SELECT RAISE(ABORT,'lifecycle observation cannot rewind'); END;
CREATE TRIGGER retained_lifecycle BEFORE DELETE ON lifecycle_observer BEGIN SELECT RAISE(ABORT,'lifecycle observation is retained'); END;
CREATE TRIGGER monotone_invitation BEFORE UPDATE ON lifecycle_invitations WHEN NEW.owner IS NOT OLD.owner OR NEW.coordinate IS NOT OLD.coordinate OR NEW.queued_at<OLD.queued_at+7200 BEGIN SELECT RAISE(ABORT,'invitation cooldown cannot rewind'); END;
CREATE TRIGGER retained_invitation BEFORE DELETE ON lifecycle_invitations BEGIN SELECT RAISE(ABORT,'invitation cooldown is retained'); END;
